        "genre": "narrative",
        "title": "La pieza dentro del vaso",
        "summary": "Una fotografía, un recuento y una nota parecen confirmar una pérdida, hasta que el grupo revisa qué había observado realmente.",
        "paragraphs": [
          "La bolsa con la batidora de mano estaba en la zona de devoluciones de la biblioteca de las cosas. En aquel local vecinal se prestaban objetos de uso ocasional, y Rosa, la adulta que lo coordinaba, revisaba los que regresaban. Noa y Adil, dos estudiantes que colaboraban allí, podían ayudar con las fotos y las anotaciones. Rosa extendió un paño y dejó encima el aparato desenchufado, con el cable recogido a un lado. La persona que lo había usado acababa de marcharse.",
          "La funda guardaba una fotografía del cuerpo, las varillas metálicas, un vaso medidor alto y un adaptador blanco. Una flecha dibujada indicaba que el adaptador unía las varillas al cuerpo. Adil fue buscando los cuatro objetos sobre el paño y solo distinguió tres. En la ficha anterior alguien había marcado el conjunto como completo. Miró esa marca, miró la foto y escribió «falta el adaptador». Noa, ocupada sujetando la funda que se cerraba sola, oyó la frase y dio por terminado el recuento.",
          "—¿Llamamos ahora? Aún estará cerca —dijo Adil.\nRosa le pidió que esperara mientras terminaba de sacar lo que quedaba en la bolsa: únicamente un paño seco. Noa acercó el vaso a la ventana para verlo mejor y lo dejó de nuevo en el mostrador. Era translúcido; entre las rayas de medida y el reflejo del cristal costaba distinguir el fondo.\n—Oye, aquí no veo hasta abajo —dijo—. ¿Lo has mirado tú?\nAdil negó con la cabeza. Había buscado la pieza al lado del vaso, donde aparecía en la foto.",
          "Rosa tomó el vaso y lo inclinó despacio sobre el paño. Sonó un golpecito. El adaptador, encajado de lado en el fondo, se movió lo suficiente para mostrar su forma. Desde arriba, su borde blanco se confundía con la base. Rosa lo extrajo y comprobó que correspondía al de la fotografía. Después examinó su estado y continuó la revisión con la batidora siempre desenchufada. Los estudiantes dejaron la manipulación del aparato en sus manos y volvieron a la ficha.",
          "—Yo ya me había imaginado a alguien buscándolo en su cocina —dijo Adil.\n—Y yo te he oído y ni he contado —admitió Noa.\nLa marca antigua seguía siendo útil para conocer cómo había salido el conjunto, pero no mostraba dónde estaba cada pieza al regresar. Tampoco la frase recién escrita era una segunda comprobación: recogía el mismo recuento incompleto. Adil la tachó y anotó el hallazgo. Por suerte, la llamada seguía siendo solo una propuesta.",
          "Al mirar de nuevo la foto de la funda, encontraron un problema más pequeño. En la foto de la funda, el adaptador tocaba el vaso y casi desaparecía contra su borde claro. Noa separó las piezas para una nueva fotografía, siguiendo las indicaciones de Rosa. Adil quiso poner al lado un dibujo enorme del vaso vacío. Al ver la foto nueva reconoció que bastaba: se distinguían los cuatro objetos y la forma de cada uno sin añadir otra página a la funda.",
          "La revisión aún no había terminado cuando guardaron las dos fotos para compararlas después. Rosa quería decidir cómo proteger las piezas en la bolsa antes de dar el conjunto por preparado para otro préstamo. Encontrar el adaptador había resuelto la sospecha de pérdida; quedaba comprobar y recoger el resto con calma. Adil se quedó sosteniendo la bolsa abierta mientras Rosa colocaba las piezas ya revisadas.",
          "Al marcharse, buscó su estuche debajo de la mochila. Noa señaló el bolsillo lateral, abierto. Adil lo sacó y miró de reojo el papel tachado que aún estaba sobre el mostrador. Los dos se rieron antes de apagar la luz de la mesa."
        ],
