        "paragraphs": [
          "La bossa amb la batedora de mà era a la zona de retorns de la biblioteca de les coses. En aquell local veïnal es prestaven objectes d’ús ocasional, i la Rosa, l’adulta que el coordinava, revisava els que tornaven. La Noa i l’Adil, dos estudiants que hi col·laboraven, podien ajudar amb les fotos i les anotacions. La Rosa va estendre un drap i hi va deixar l’aparell desendollat, amb el cable recollit a un costat. La persona que l’havia fet servir acabava d’anar-se’n.",
          "La funda guardava una fotografia del cos, les varetes metàl·liques, un vas mesurador alt i un adaptador blanc. Una fletxa dibuixada indicava que l’adaptador unia les varetes al cos. L’Adil va anar buscant els quatre objectes damunt el drap i només en va distingir tres. A la fitxa anterior algú havia marcat el conjunt com a complet. Va mirar aquella marca, va mirar la foto i va escriure «falta l’adaptador». La Noa, ocupada aguantant la funda que es tancava sola, va sentir la frase i va donar el recompte per acabat.",
          "—Truquem ara? Encara serà a prop —va dir l’Adil.\nLa Rosa li va demanar que esperés mentre acabava de treure el que quedava a la bossa: únicament un drap sec. La Noa va acostar el vas a la finestra per veure’l millor i el va tornar a deixar al taulell. Era translúcid; entre les ratlles de mesura i el reflex del vidre costava distingir el fons.\n—Escolta, aquí no veig fins a baix —va dir—. Tu l’has mirat?\nL’Adil va negar amb el cap. Havia buscat la peça al costat del vas, on apareixia a la foto.",
          "La Rosa va agafar el vas i el va inclinar a poc a poc damunt el drap. Va sonar un copet. L’adaptador, encaixat de costat al fons, es va moure prou per mostrar la forma. Des de dalt, la vora blanca es confonia amb la base. La Rosa el va extreure i va comprovar que corresponia al de la fotografia. Després en va examinar l’estat i va continuar la revisió amb la batedora sempre desendollada. Els estudiants van deixar la manipulació de l’aparell a les seves mans i van tornar a la fitxa.",
          "—Jo ja m’havia imaginat algú buscant-lo a la cuina de casa —va dir l’Adil.\n—I jo t’he sentit i ni he comptat —va admetre la Noa.\nLa marca antiga continuava sent útil per saber com havia sortit el conjunt, però no mostrava on era cada peça en tornar. Tampoc la frase acabada d’escriure era una segona comprovació: recollia el mateix recompte incomplet. L’Adil la va ratllar i va anotar la troballa. Per sort, la trucada continuava sent només una proposta.",
          "En tornar a mirar la foto de la funda, van trobar un problema més petit. A la foto de la funda, l’adaptador tocava el vas i gairebé desapareixia contra la vora clara. La Noa va separar les peces per a una fotografia nova, seguint les indicacions de la Rosa. L’Adil va voler posar-hi al costat un dibuix enorme del vas buit. En veure la foto nova va reconèixer que ja n’hi havia prou: es distingien els quatre objectes i la forma de cadascun sense afegir una altra pàgina a la funda.",
          "La revisió encara no havia acabat quan van desar les dues fotos per comparar-les després. La Rosa volia decidir com protegir les peces a la bossa abans de donar el conjunt per preparat per a un altre préstec. Trobar l’adaptador havia resolt la sospita de pèrdua; quedava comprovar i recollir la resta amb calma. L’Adil es va quedar aguantant la bossa oberta mentre la Rosa hi col·locava les peces ja revisades.",
          "En anar-se’n, va buscar l’estoig sota la motxilla. La Noa va assenyalar la butxaca lateral, oberta. L’Adil el va treure i va mirar de reüll el paper ratllat que encara era damunt el taulell. Tots dos van riure abans d’apagar el llum de la taula."
        ],
