        "genre": "news",
        "title": "La parada cambió de centro",
        "summary": "Una crónica del mercado cuenta cómo las preguntas del público cambiaron la presentación de la biblioteca de objetos.",
        "paragraphs": [
          "La biblioteca de las cosas salió este sábado al mercado con una mesa, un proyector y varias fotografías. El servicio, situado en un local de la asociación vecinal, presta objetos que se necesitan de forma ocasional. Rosa, su coordinadora, atendió la parada con Noa y Adil, dos estudiantes colaboradores. Querían llegar a personas que pasaban por delante del local sin entrar. Esta crónica del boletín vecinal recoge lo ocurrido durante la mañana.",
          "El proyector ocupaba el centro de la mesa. «Pensaba que preguntarían por películas o por una fiesta», explicó Noa después. Pero las primeras preguntas fueron para el carro plegable que habían usado para llevar los folletos y que habían dejado debajo. Una mujer con dos bolsas llenas se agachó para verlo. Quiso saber si también se prestaba, cuánto ocupaba cerrado y si se podía llegar andando al local desde el mercado.",
          "Rosa sacó el carro y mostró cómo se doblaba. Otro visitante preguntó cuánto costaba comprarlo. Ella le explicó que pertenecía al servicio: los objetos se llevaban durante un tiempo y después se devolvían. El carro estaba ocupado aquella mañana por el propio equipo. Para pedirlo otro día habría que comprobar si estaba libre. El visitante tomó un folleto y señaló en el mapa la calle por la que solía volver a casa.",
          "Las preguntas sobre el carro se repitieron. Adil propuso dejarlo delante para que nadie tuviera que agacharse. Lo dejaron abierto delante, fuera del paso, con una caja vacía dentro para mostrar su capacidad. El proyector pasó a un lateral y siguió visible. También acercaron el mapa al borde de la mesa: varias personas conocían la calle del local, pero no sabían reconocer su entrada.",
          "Una familia preguntó por el proyector para una fiesta y dos vecinos se detuvieron ante la fotografía de una máquina de coser. El carro no había eliminado esos intereses; había abierto una conversación que el equipo no había preparado. «Yo tenía lista la explicación del proyector y he acabado enseñando el camino», contó Noa. Rosa guardó las preguntas más repetidas para revisar el folleto antes de la próxima salida.",
          "Al recoger, el equipo había anotado dieciocho conversaciones. No contaron a quienes solo miraron la mesa o cogieron un papel. Tampoco eran dieciocho préstamos: en la parada se informaba y las entregas se hacían en el local. La cifra permite saber cuántas charlas registraron, aunque por sí sola no indica cuántas personas terminarán usando el servicio ni qué objeto pedirán.",
          "El carro volvió con la caja vacía y los folletos sobrantes. Rosa anunció otra visita al mercado para el mes siguiente, todavía sin fecha concreta. Noa pidió que la próxima vez dejaran el carro a la vista desde el principio."
        ],
