        "title": "La parada va canviar de centre",
        "summary": "La biblioteca canvia la parada després d’escoltar el públic. La crònica distingeix què permeten saber les converses i què encara queda obert.",
        "paragraphs": [
          "La biblioteca de les coses es va presentar aquest dissabte al mercat amb una parada informativa. El servei presta objectes d’ús ocasional des d’un local de l’associació veïnal. La Rosa, l’adulta que el coordina, hi va anar amb la Noa i l’Adil, dos estudiants col·laboradors. Van portar un projector, fotografies d’altres objectes i fullets amb un mapa del local. La visita pretenia arribar a qui coneixia aquell carrer, però passava de llarg. Aquesta crònica del butlletí veïnal combina l’observació del matí amb els comentaris de l’equip en recollir.",
          "El projector va començar al centre de la taula, dirigit cap al passadís del mercat. Estava apagat: l’havien portat per mostrar-lo, no per projectar. «Jo tenia preparada l’explicació de com demanar-lo per a una festa», va explicar la Noa més tard. Esperava que fos el gran reclam. Tanmateix, les primeres preguntes es van dirigir al carret plegable que l’equip havia fet servir per transportar els papers. L’havien desat sota la taula, amb els fullets sobrants a dins.",
          "Una dona que portava dues bosses plenes es va ajupir per assenyalar-lo. Va preguntar si es prestava, quant ocupava tancat i per on podia arribar caminant al local. La Rosa el va treure i va assenyalar les parts que es doblegaven. Un altre visitant va preguntar el preu de compra. Ella va explicar que els objectes s’agafaven durant un temps i havien de tornar al local. Aquell carret l’estava fent servir el mateix equip durant el matí; per fer-lo servir un altre dia caldria consultar si estava lliure.",
          "Després de diverses converses semblants, l’Adil va proposar canviar la disposició. Van treure els papers, van obrir el carret davant de la taula, fora del pas, i hi van posar una caixa buida. Així se’n veia la capacitat sense que ningú s’hagués d’ajupir. El projector va quedar en un lateral, encara a la vista. També van acostar el mapa a la vora: alguns visitants reconeixien el carrer, però necessitaven una referència per trobar la porta. La Noa va començar a assenyalar el camí abans d’explicar els objectes.",
          "El canvi no va deixar el projector sense públic. Una família hi va preguntar per a una festa; dos veïns es van interessar per la fotografia d’una màquina de cosir. El carret havia permès iniciar altres converses, especialment entre persones que ja portaven compres. «L’hem portat per carregar els papers i hem acabat traient-lo en gairebé totes les xerrades», va recordar l’Adil. La seva impressió descriu aquell matí; l’equip no havia preguntat pels mateixos objectes a totes les persones que passaven.",
          "En total van anotar divuit converses. Van quedar fora del recompte qui només va mirar o va agafar un fullet. A la parada s’informava; els objectes es lliuraven al local, on es preparaven els préstecs. Per això, la xifra de xerrades no permet calcular quants préstecs hi haurà ni convertir el carret en l’objecte preferit de tot el barri. A més, qui no va anar al mercat o no s’hi va aturar no apareix en aquestes notes. La Rosa va conservar les preguntes repetides per millorar l’explicació del servei.",
          "Abans de tancar, van revisar el fullet que havien repartit. Tenia una fotografia gran del projector i el mapa en un racó petit. La Noa va assenyalar que li havia costat ensenyar-lo sense tapar-lo amb els dits. La Rosa va proposar ampliar el mapa i afegir una imatge del carret plegat. Prepararien una prova per a la visita següent, prevista per al mes següent i encara sense data concreta.",
          "En tornar, el carret va tornar a portar els fullets i la caixa buida. El projector va viatjar a la funda. Aquest cop havien desat el mapa damunt de tot."
        ],
